10	/// Registers the `auth` feature into the project's single `get_it` instance
11	/// (`sl`). Called from `setupCoreDependencies()` once core infrastructure is
12	/// up, since this feature only needs `ApiClient`/`AccessTokenProvider`,
13	/// already registered there.
14	void registerAuthFeature() {
15	  sl.registerLazySingleton<AuthRemoteDataSource>(
16	    () => AuthRemoteDataSource(sl()),
17	  );
18	
19	  sl.registerLazySingleton<AuthRepository>(
20	    () => AuthRepositoryImpl(
21	      remoteDataSource: sl(),
22	      accessTokenProvider: sl<AccessTokenProvider>(),
23	    ),
24	  );
25	
26	  // The epic's ONE new DI-singleton access point for session validity (AD) —
27	  // registered as a singleton so every consumer (`main.dart` here; Story
28	  // 1.5's overlay and Story 1.6's `go_router` redirect later) shares the
29	  // same `statusStream`, not a fresh instance each. `dispose:` wires
30	  // `SessionRepository.dispose()` into `get_it`'s own reset lifecycle, so
31	  // `resetCoreDependencies()` (`sl.reset()`) closes its `StreamController`
32	  // instead of leaking one on every test teardown.
33	  sl.registerLazySingleton<SessionRepository>(
34	    () => SessionRepositoryImpl(
35	      remoteDataSource: sl(),
36	      accessTokenProvider: sl<AccessTokenProvider>(),
37	    ),
38	    dispose: (repository) => repository.dispose(),
39	  );
40	
41	  sl.registerLazySingleton<AuthCubit>(() => AuthCubit(sl()));
42	}
