139	  // handler would try to complete it with `null`, which isn't assignable
140	  // to that non-nullable type and would itself throw.
141	  static Either<Failure, Unit> _asUnauthenticated(
142	    Object error,
143	    StackTrace stackTrace,
144	  ) {
