166	          // different widget for it (Boundaries: "the authenticated
167	          // screen's widget instance is never replaced across
168	          // authenticated<->expired transitions").
169	          if (snapshot.data == SessionStatus.authenticated ||
170	              snapshot.data == SessionStatus.expired) {
171	            return const _PostAuthPlaceholder();
172	          }
