                        context: context,
                        builder: (_) => ConfirmationDialog(
                          icon: Icons.lock_outline,
                          title: 'Second overlay',
                          message: 'Second message.',
                          confirmLabel: 'Ok',
                          barrierColor: DesignTokens.colorScrim,
