      var confirmed = false;
      await tester.pumpWidget(
        _appWithOpenButton(onConfirm: () => confirmed = true),
      );
      await tester.tap(find.text('Open'));
      await tester.pumpAndSettle();

      await tester.tap(find.text('Entrar novamente'));
