1	import 'dart:async';
2	
3	import 'package:flutter/material.dart';
4	import 'package:fpdart/fpdart.dart' hide State;
5	
6	import 'core/design_tokens.dart';
7	import 'core/di/injection_container.dart';
8	import 'core/failure/failure.dart';
9	import 'core/widgets/confirmation_dialog.dart';
10	import 'features/auth/domain/entities/session_status.dart';
11	import 'features/auth/domain/repositories/session_repository.dart';
12	import 'features/auth/presentation/cubit/auth_cubit.dart';
13	import 'features/auth/presentation/screens/auth_screen.dart';
14	
15	Future<void> main() async {
16	  WidgetsFlutterBinding.ensureInitialized();
17	  try {
18	    await setupCoreDependencies();
19	  } catch (error) {
20	    debugPrint(
21	      'Cerne failed to start: could not load .env ($error). Copy '
22	      '.env.example to .env and fill in FUNCTIONS_BASE_URL + '
23	      'SUPABASE_ANON_KEY before running the app.',
24	    );
25	    rethrow;
26	  }
27	  runApp(const CerneApp());
28	}
29	
30	/// Root widget. Portrait-only, light-mode-only, fixed 390x844 frame — no
31	/// breakpoint, landscape or dark-mode path anywhere in the app (per the
32	/// epic's UX constraints).
33	///
34	/// Story 1.4 scope: `home` branches on `SessionRepository.statusStream`
35	/// instead of hardcoding `AuthScreen` — `restoreSession()` fires once at
36	/// boot (unconditional, no client-side expiry math) and the stream's first
37	/// emission decides whether the user lands on `AuthScreen` or the post-auth
38	/// placeholder. No `go_router` yet (Story 1.6): the `MaterialApp`/`Navigator`
39	/// shape is unchanged, and a successful signup/login still simply
40	/// pushes-replaces via `onAuthenticated`.
41	///
42	/// Story 1.5 scope: a mid-session expiry (the same stream's `expired`
43	/// value) never changes which screen `home` renders — it only triggers a
44	/// `ConfirmationDialog` overlay on top of it, shown/dismissed by a second
45	/// stream subscription kept independent of the `StreamBuilder` below.
46	class CerneApp extends StatefulWidget {
47	  const CerneApp({super.key});
48	
49	  @override
50	  State<CerneApp> createState() => _CerneAppState();
51	}
52	
53	class _CerneAppState extends State<CerneApp> {
54	  late final SessionRepository _sessionRepository;
55	
56	  // Cached once: `SessionRepository.statusStream`'s getter builds a new
57	  // `Stream.multi` instance on every access (code review of
58	  // story-1-4-silent-session-refresh-persistence), so reading it straight
59	  // into `StreamBuilder.stream` on every `build()` would make it resubscribe
60	  // and lose its current status on each rebuild instead of staying on one
61	  // subscription for this widget's lifetime.
62	  late final Stream<SessionStatus> _statusStream;
